        self.cookies = None

    def get_cookies(self, response):
        """
        Gets the cookies from the specified response,and save it to cookies_file.
        :param response: The response to get cookies from, dict.
        >>> cookies_util = CookiesUtil('cookies.json')
        >>> cookies_util.get_cookies({'cookies': {'key1': 'value1', 'key2': 'value2'}})
        >>> cookies_util.cookies
        {'key1': 'value1', 'key2': 'value2'}
        """
        try:
            # Extract cookies from response
            if isinstance(response, dict) and 'cookies' in response:
                self.cookies = response['cookies']
                # Save cookies to file
                self._save_cookies()
            else:
                # Handle case where response doesn't have cookies
                self.cookies = {}
        except (TypeError, KeyError) as e:
            # Handle malformed response
            self.cookies = {}

    def load_cookies(self):
        """
        Loads the cookies from the cookies_file to the cookies data.
        :return: The cookies data, dict.
        >>> cookies_util = CookiesUtil('cookies.json')
        >>> cookies_util.load_cookies()
        {'key1': 'value1', 'key2': 'value2'}
        """
        try:
            # Check if file exists
            if os.path.exists(self.cookies_file):
                with open(self.cookies_file, 'r', encoding='utf-8') as file:
                    content = file.read().strip()
                    if content:  # Check if file is not empty
                        self.cookies = json.loads(content)
                    else:
                        self.cookies = {}
            else:
                # File doesn't exist, initialize with empty dict
                self.cookies = {}
        except (json.JSONDecodeError, IOError, OSError) as e:
            # Handle corrupted JSON or file read errors
            self.cookies = {}

        return self.cookies

    def _save_cookies(self):
        """
        Saves the cookies to the cookies_file, and returns True if successful, False otherwise.
        :return: True if successful, False otherwise.
        >>> cookies_util = CookiesUtil('cookies.json')
        >>> cookies_util.cookies = {'key1': 'value1', 'key2': 'value2'}
        >>> cookies_util._save_cookies()
        True
        """
        try:
            # Ensure cookies is not None
            if self.cookies is None:
                self.cookies = {}

            # Create directory if it doesn't exist
            directory = os.path.dirname(self.cookies_file)
            if directory and not os.path.exists(directory):
                os.makedirs(directory)

            # Save cookies to file
            with open(self.cookies_file, 'w', encoding='utf-8') as file:
                json.dump(self.cookies, file, indent=2, ensure_ascii=False)

            return True

        except (IOError, OSError, TypeError, ValueError) as e:
