class ExpressionCalculator:
    """
    This is a class in Python that can perform calculations with basic arithmetic operations, including addition, subtraction, multiplication, division, and modulo.
    """

    def __init__(self):
        """
        Initialize the expression calculator
        """
        self.postfix_stack = deque()
        # Operator precedence mapping: +, -, *, /, (, ), %
        # Index mapping: + -> 0, - -> 1, * -> 2, / -> 3, ( -> 4, ) -> 5, % -> 6
        self.operat_priority = {
            '+': 1, '-': 1, '*': 2, '/': 2, '%': 2, '(': 0, ')': 0
        }

    def calculate(self, expression):
        """
        Calculate the result of the given postfix expression
        :param expression: string, the postfix expression to be calculated
        :return: float, the calculated result
        """
        # Transform and prepare the expression
        transformed_expr = self.transform(expression)
        self.prepare(transformed_expr)

        # Evaluate the postfix expression
        eval_stack = []

        for token in self.postfix_stack:
            if self.is_operator(token):
                if len(eval_stack) < 2:
                    raise ValueError("Invalid expression: insufficient operands")

                second = eval_stack.pop()
                first = eval_stack.pop()
                result = self._calculate(str(first), str(second), token)
                eval_stack.append(float(result))
            else:
                eval_stack.append(float(token))

        if len(eval_stack) != 1:
            raise ValueError("Invalid expression")

        return eval_stack[0]

    def prepare(self, expression):
        """
        Prepare the infix expression for conversion to postfix notation
        :param expression: string, the infix expression to be prepared
        """
        self.postfix_stack.clear()
        operator_stack = []
        i = 0

        while i < len(expression):
            char = expression[i]

            if char.isdigit() or char == '.':
                # Handle multi-digit numbers and decimals
                num = ''
                while i < len(expression) and (expression[i].isdigit() or expression[i] == '.'):
                    num += expression[i]
                    i += 1
                self.postfix_stack.append(num)
                continue

            elif char == '(':
                operator_stack.append(char)

            elif char == ')':
                # Pop operators until we find the opening parenthesis
                while operator_stack and operator_stack[-1] != '(':
                    self.postfix_stack.append(operator_stack.pop())
                if operator_stack:
                    operator_stack.pop()  # Remove the '('

            elif self.is_operator(char):
                # Pop operators with higher or equal precedence
                while (operator_stack and 
                       operator_stack[-1] != '(' and
                       self.compare(operator_stack[-1], char)):
                    self.postfix_stack.append(operator_stack.pop())
                operator_stack.append(char)

            i += 1

        # Pop remaining operators
        while operator_stack:
            self.postfix_stack.append(operator_stack.pop())

    @staticmethod
    def is_operator(c):
        """
        Check if a character is an operator in {'+', '-', '*', '/', '(', ')', '%'}
        :param c: string, the character to be checked
        :return: bool, True if the character is an operator, False otherwise
        """
        return c in {'+', '-', '*', '/', '(', ')', '%'}

    def compare(self, peek, cur):
        """
        Compare the precedence of two operators
        :param peek: string, the operator at the top of the operator stack
        :param cur: string, the current operator
        :return: bool, True if peek has higher or equal precedence than cur, False otherwise
        """
        if peek not in self.operat_priority or cur not in self.operat_priority:
            return False
        return self.operat_priority[peek] >= self.operat_priority[cur]

    @staticmethod
    def _calculate(first_value, second_value, current_op):
        """
        Perform the mathematical calculation based on the given operands and operator
        :param first_value: string, the first operand
        :param second_value: string, the second operand
        :param current_op: string, the operator
        :return: float, the calculated result
        """
        first = Decimal(first_value)
        second = Decimal(second_value)

        if current_op == '+':
            return float(first + second)
        elif current_op == '-':
            return float(first - second)
        elif current_op == '*':
            return float(first * second)
        elif current_op == '/':
            if second == 0:
                raise ZeroDivisionError("Division by zero")
            return float(first / second)
        elif current_op == '%':
            if second == 0:
                raise ZeroDivisionError("Modulo by zero")
            return float(first % second)
        else:
            raise ValueError(f"Unknown operator: {current_op}")

    @staticmethod
    def transform(expression):
        """
        Transform the infix expression to a format suitable for conversion
        :param expression: string, the infix expression to be transformed
        :return: string, the transformed expression
        """
        # Remove all whitespace characters
        return ''.join(expression.split())

