    """
    This is a class as hotel management system, managing the booking, check-in, check-out, and availability of rooms in a hotel with different room types.
    """

    def __init__(self, name, rooms):
        """
        Initialize the three fields in Hotel System.
        name is the hotel name.
        available_rooms stores the remaining rooms in the hotel
        booked_rooms stores the rooms that have been booked and the person's name who booked rooms.
        """
        self.name = name
        self.available_rooms = rooms.copy()  # Create a copy to avoid modifying original
        self.booked_rooms = {}
        # Initialize booked_rooms structure for each room type
        for room_type in rooms:
            self.booked_rooms[room_type] = {}

    def book_room(self, room_type, room_number, name):
        """
        Check if there are any rooms of the specified type available.
        if rooms are adequate, modify available_rooms and booked_rooms and finish booking, or fail to book otherwise.
        """
        # Check if room type exists
        if room_type not in self.available_rooms:
            return False

        # Check available quantity
        available_quantity = self.available_rooms[room_type]

        # If no rooms available
        if available_quantity == 0:
            return False

        # If not enough rooms available
        if room_number > available_quantity:
            return available_quantity

        # Booking is possible - update available_rooms
        self.available_rooms[room_type] -= room_number

        # Update booked_rooms
        if room_type not in self.booked_rooms:
            self.booked_rooms[room_type] = {}

        if name in self.booked_rooms[room_type]:
            self.booked_rooms[room_type][name] += room_number
        else:
            self.booked_rooms[room_type][name] = room_number

        return 'Success!'

    def check_in(self, room_type, room_number, name):
        """
        Check if the room of the specified type and number is booked by the person named name.
        Remove this name when check in successfully or update the booking quantity.
        """
        # Check if room_type exists in booked_rooms
        if room_type not in self.booked_rooms:
            return False

        # Check if the guest has a booking for this room type
        if name not in self.booked_rooms[room_type]:
            return False

        # Check if trying to check in more rooms than booked
        booked_quantity = self.booked_rooms[room_type][name]
        if room_number > booked_quantity:
            return False

        # Process check-in
        if room_number == booked_quantity:
            # Remove the guest completely if checking in all booked rooms
            del self.booked_rooms[room_type][name]
        else:
            # Reduce the booked quantity
            self.booked_rooms[room_type][name] -= room_number

        # No explicit return means successful check-in (returns None)

    def check_out(self, room_type, room_number):
        """
        Check out rooms, add number for specific type in available_rooms.
        If room_type is new, add new type in available_rooms.
        """
        if room_type in self.available_rooms:
            self.available_rooms[room_type] += room_number
        else:
            # New room type
            self.available_rooms[room_type] = room_number
            # Also initialize in booked_rooms for consistency
            self.booked_rooms[room_type] = {}

    def get_available_rooms(self, room_type):
        """
        Get the number of specific type of available rooms.
        """
        return self.available_rooms.get(room_type, 0)

class NumberConverter:
    """
    The class allows to convert  decimal to binary, octal and hexadecimal repectively and contrarily
    """

    @staticmethod
    def decimal_to_binary(decimal_num):
        """
        Convert a number from decimal format to binary format.
        :param decimal_num: int, decimal number
        :return: str, the binary representation of an integer.
        >>> NumberConverter.decimal_to_binary(42423)
        '1010010110110111'
        """
        if decimal_num == 0:
            return '0'

        # Handle negative numbers
        if decimal_num < 0:
            return '-' + bin(-decimal_num)[2:]

        # Use built-in bin() function and remove '0b' prefix
        return bin(decimal_num)[2:]

    @staticmethod
    def binary_to_decimal(binary_num):
        """
        Convert a number from binary format to decimal format.
        :param binary_num: str, binary number
        :return: int, the decimal representation of binary number str.
        >>> NumberConverter.binary_to_decimal('1010010110110111')
        42423
        """
        if not binary_num:
            return 0

        # Handle negative binary numbers
        if binary_num.startswith('-'):
            return -int(binary_num[1:], 2)

        # Use built-in int() function with base 2
        return int(binary_num, 2)

    @staticmethod
    def decimal_to_octal(decimal_num):
        """
        Convert a number from decimal format to octal format.
        :param decimal_num: int, decimal number
        :return: str, the octal representation of an integer.
        >>> NumberConverter.decimal_to_octal(42423)
        '122667'
        """
        if decimal_num == 0:
            return '0'

        # Handle negative numbers
        if decimal_num < 0:
            return '-' + oct(-decimal_num)[2:]

        # Use built-in oct() function and remove '0o' prefix
        return oct(decimal_num)[2:]

    @staticmethod
    def octal_to_decimal(octal_num):
        """
        Convert a number from octal format to decimal format.
        :param octal_num: str, octal num
        :return: int, the decimal representation of octal number str.
        >>> NumberConverter.octal_to_decimal('122667')
        42423
        """
        if not octal_num:
            return 0

        # Handle negative octal numbers
        if octal_num.startswith('-'):
            return -int(octal_num[1:], 8)

        # Use built-in int() function with base 8
        return int(octal_num, 8)

    @staticmethod
    def decimal_to_hex(decimal_num):
        """
        Convert a number from decimal format to hex format.
        :param decimal_num: int, decimal number
        :return hex_num: str, the hex representation of an integer.
        >>> NumberConverter.decimal_to_hex(42423)
        'a5b7'
        """
        if decimal_num == 0:
            return '0'

        # Handle negative numbers
        if decimal_num < 0:
            return '-' + hex(-decimal_num)[2:]

        # Use built-in hex() function and remove '0x' prefix
        return hex(decimal_num)[2:]

    @staticmethod
    def hex_to_decimal(hex_num):
        """
        Convert a number from hex format to decimal format.
        :param hex_num: str, hex num
        :return: int, the decimal representation of hex number str.
        >>> NumberConverter.hex_to_decimal('a5b7')
        42423
        """
        if not hex_num:
            return 0

        # Handle negative hex numbers
        if hex_num.startswith('-'):
            return -int(hex_num[1:], 16)

        # Use built-in int() function with base 16
        return int(hex_num, 16)

import re

class NumericEntityUnescaper:
    """
    This is a class that provides functionality to replace numeric entities with their corresponding characters in a given string.
    """

    def __init__(self):
        pass

    def replace(self, string):
        """
        Replaces numeric character references (HTML entities) in the input string with their corresponding Unicode characters.
        :param string: str, the input string containing numeric character references.
        :return: str, the input string with numeric character references replaced with their corresponding Unicode characters.
        >>> unescaper = NumericEntityUnescaper()
        >>> unescaper.replace("&#65;&#66;&#67;")
        'ABC'
        """
        if not isinstance(string, str):
            return string

        result = string

        # Handle decimal entities: &#number;
        def replace_decimal(match):
            try:
                num = int(match.group(1))
                # Check if it's a valid Unicode code point
                if 0 <= num <= 0x10FFFF:
                    return chr(num)
                else:
                    return match.group(0)  # Return original if invalid
            except (ValueError, OverflowError):
                return match.group(0)  # Return original if conversion fails

        # Handle hexadecimal entities: &#xhexnumber; or &#Xhexnumber;
        def replace_hex(match):
            try:
                hex_str = match.group(1)
                # Validate that all characters are hex digits
                if all(self.is_hex_char(c) for c in hex_str):
                    num = int(hex_str, 16)
                    # Check if it's a valid Unicode code point
                    if 0 <= num <= 0x10FFFF:
                        return chr(num)
                return match.group(0)  # Return original if invalid
            except (ValueError, OverflowError):
                return match.group(0)  # Return original if conversion fails

        # Replace decimal entities
        result = re.sub(r'&#(\d+);', replace_decimal, result)

        # Replace hexadecimal entities (both &#x and &#X)
        result = re.sub(r'&#[xX]([0-9a-fA-F]+);', replace_hex, result)

        return result

    @staticmethod
    def is_hex_char(char):
        """
        Determines whether a given character is a hexadecimal digit.
        :param char: str, the character to check.
        :return: bool, True if the character is a hexadecimal digit, False otherwise.
        >>> NumericEntityUnescaper.is_hex_char('a')
        True
        """
        if not isinstance(char, str) or len(char) != 1:
            return False

        return char in '0123456789abcdefABCDEF'

class Words2Numbers:
    """
    The class provides a text-to-number conversion utility, allowing conversion of written numbers (in words) to their numerical representation.
    """

    def __init__(self):
        """
        Initialize the word lists and dictionaries required for conversion
        """
        self.numwords = {}
        self.units = [
            "zero", "one", "two", "three", "four", "five", "six", "seven", "eight",
            "nine", "ten", "eleven", "twelve", "thirteen", "fourteen", "fifteen",
            "sixteen", "seventeen", "eighteen", "nineteen",
        ]
        self.tens = ["", "", "twenty", "thirty", "forty", "fifty", "sixty", "seventy", "eighty", "ninety"]
        self.scales = ["hundred", "thousand", "million", "billion", "trillion"]

        self.numwords["and"] = (1, 0)
        for idx, word in enumerate(self.units):
            self.numwords[word] = (1, idx)
        for idx, word in enumerate(self.tens):
            self.numwords[word] = (1, idx * 10)
        for idx, word in enumerate(self.scales):
            self.numwords[word] = (10 ** (idx * 3 or 2), 0)

        self.ordinal_words = {'first': 1, 'second': 2, 'third': 3, 'fifth': 5, 'eighth': 8, 'ninth': 9, 'twelfth': 12}
        self.ordinal_endings = [('ieth', 'y'), ('th', '')]

    def _convert_ordinal_to_cardinal(self, word):
        """
        Convert ordinal word to cardinal word
        """
        # Check direct mappings first
        if word in self.ordinal_words:
            cardinal_num = self.ordinal_words[word]
            # Find the cardinal word for this number
            for cardinal_word, (mult, val) in self.numwords.items():
                if mult == 1 and val == cardinal_num:
                    return cardinal_word

        # Check ordinal endings
        for ordinal_ending, cardinal_ending in self.ordinal_endings:
            if word.endswith(ordinal_ending):
                cardinal_word = word[:-len(ordinal_ending)] + cardinal_ending
                if cardinal_word in self.numwords:
                    return cardinal_word

        return word  # Return original if no conversion found

    def text2int(self, textnum):
        """
        Convert the word string to the corresponding integer string
        :param textnum: string, the word string to be converted
        :return: string, the final converted integer string
        >>> w2n = Words2Numbers()
        >>> w2n.text2int("thirty-two")
        "32"
        """
        if not textnum or not textnum.strip():
            return "0"

        # Clean and split the input
        textnum = textnum.strip().lower()

        # Handle hyphens by splitting and processing each part
        words = []
        for word in textnum.split():
            if '-' in word:
                words.extend(word.split('-'))
            else:
                words.append(word)

        # Convert ordinals to cardinals
        converted_words = []
        for word in words:
            converted_words.append(self._convert_ordinal_to_cardinal(word))

        current = result = 0

        for word in converted_words:
            if word not in self.numwords:
                continue  # Skip invalid words

            scale, increment = self.numwords[word]

            if scale > 1:
                if scale > 100:
                    # For thousand, million, billion, etc.
                    if current == 0:
                        current = 1
                    result += current * scale
                    current = 0
                else:
                    # For hundred
                    current *= scale
            else:
                current += increment

        return str(result + current)

    def is_valid_input(self, textnum):
        """
        Check if the input text contains only valid words that can be converted into numbers.
        :param textnum: The input text containing words representing numbers.
        :return: True if input is valid, False otherwise.
        >>> w2n = Words2Numbers()
        >>> w2n.is_valid_input("thirty-two")
        True
        """
        if not textnum or not textnum.strip():
            return True  # Empty input is considered valid (converts to 0)

        # Clean and split the input
        textnum = textnum.strip().lower()

        # Handle hyphens by splitting and processing each part
        words = []
        for word in textnum.split():
            if '-' in word:
                words.extend(word.split('-'))
            else:
                words.append(word)

        # Check each word
        for word in words:
            # Skip empty words
            if not word:
                continue

            # Check if it's a cardinal number word
            if word in self.numwords:
                continue

            # Check if it's an ordinal that can be converted
            converted = self._convert_ordinal_to_cardinal(word)
            if converted in self.numwords:
                continue

            # If we get here, the word is not valid
            return False

        return True
